1	/* ──────────────────────────────────────────────────────────────────────────
2	   Admin workspace theme
3	   One theme for every /admin screen and every new admin app. The public site
4	   (:root / .dark site tokens) and .print-preview-container are not touched.
5	
6	   Scope: `.admin-tool` (the AdminLayout shell, and dialogs that opt in) plus
7	   `body.ws-admin`, a class AdminLayout sets on <body> while mounted so portaled
8	   popovers, menus and dialogs resolve the same tokens.
9	
10	   All --ws-* colour tokens are HSL triplets so hsl(var(--ws-x)) and
11	   hsl(var(--ws-x) / a) both work. Legacy --admin-* names are re-pointed to
12	   these tokens in index.css; do not delete them.
13	   ────────────────────────────────────────────────────────────────────────── */
14	
15	.admin-tool,
16	body.ws-admin {
17	  --ws-paper: 0 0% 100%;
18	  --ws-bg: 43 28% 95%;
19	  --ws-side: 45 25% 94%;
20	  --ws-side-hover: 44 20% 89%;
21	  --ws-ink: 214 46% 16%;
22	  --ws-ink-2: 215 17% 37%;
23	  --ws-ink-3: 215 12% 59%;
24	  --ws-line: 40 23% 87%;
25	  --ws-input-border: 41 16% 80%;
26	  --ws-accent: 188 71% 36%;
27	  --ws-accent-fg: 0 0% 100%;
28	  --ws-accent-tint: 188 40% 92%;
29	  --ws-accent-line: 38 61% 49%;
30	  --ws-navy: 213 66% 13%;
31	  --ws-thumb: 215 9% 58%;
32	
33	  /* Hover / press fills and selection (full colours, not triplets) */
34	  --ws-hover: hsl(var(--ws-ink) / 0.055);
35	  --ws-press: hsl(var(--ws-ink) / 0.09);
36	  --ws-selection: hsl(var(--ws-accent) / 0.2);
37	
38	  /* Shape */
39	  --ws-radius-block: 4px;   /* blocks, pills, inputs, table cells */
40	  --ws-radius-control: 6px; /* buttons, menu items */
41	  --ws-radius-float: 8px;   /* popovers, cards */
42	
43	  /* Type */
44	  --ws-font-sans: 'Plus Jakarta Sans', ui-sans-serif, system-ui, sans-serif;
45	  --ws-font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
46	}
47	
48	.dark .admin-tool,
49	.dark body.ws-admin {
50	  --ws-paper: 212 48% 11%;
51	  --ws-bg: 211 57% 7%;
52	  --ws-side: 211 51% 9%;
53	  --ws-side-hover: 210 38% 13%;
54	  --ws-ink: 213 26% 92%;
55	  --ws-ink-2: 214 17% 71%;
56	  --ws-ink-3: 213 13% 48%;
57	  --ws-line: 213 34% 18%;
58	  --ws-input-border: 213 29% 23%;
59	  --ws-accent: 188 53% 51%;
60	  --ws-accent-fg: 206 66% 7%;
61	  --ws-accent-tint: 197 54% 15%;
62	  --ws-accent-line: 188 53% 51%;
63	  --ws-navy: 213 66% 13%;
64	  --ws-thumb: 188 53% 51%;
65	
66	  --ws-selection: hsl(var(--ws-accent) / 0.28);
67	}
68	
