1	import { useEffect } from "react";
2	import type { ReactNode } from "react";
3	import { Navigate, useParams } from "react-router";
4	import { AdminRoleProvider } from "@/contexts/AdminRoleContext";
5	import { useAdminBodyClass } from "@/hooks/useAdminBodyClass";
6	import { useScrollingClass } from "@/hooks/useScrollingClass";
7	import AtlasWorkspace from "./AtlasWorkspace";
8	import { ATLAS_CONFIG, atlasPath } from "./config";
9	import { useAtlasCapabilities } from "./hooks/useAtlas";
10	import { getAtlasHost } from "./host";
11	import { useStandaloneDisplay } from "./hooks/useStandaloneDisplay";
12	import { getAtlasSpace, listAtlasSpaces } from "./spaces";
13	
14	const MANIFEST_ID = "atlas-manifest";
15	
16	/**
17	 * Atlas is installable: its manifest is linked only while an Atlas route is mounted, and a minimal
18	 * service worker (app shell only, scoped to /atlas/) is registered. Registration failures are
19	 * ignored: the app works the same without it.
20	 */
21	const useAtlasInstall = () => {
22	  useEffect(() => {
23	    let link: HTMLLinkElement | null = null;
24	    if (!document.getElementById(MANIFEST_ID)) {
25	      link = document.createElement("link");
26	      link.id = MANIFEST_ID;
27	      link.rel = "manifest";
28	      link.href = `${ATLAS_CONFIG.basePath}.webmanifest`;
29	      document.head.appendChild(link);
30	    }
31	    if ("serviceWorker" in navigator) {
32	      navigator.serviceWorker.register(`${ATLAS_CONFIG.basePath}-sw.js`, { scope: `${ATLAS_CONFIG.basePath}/` }).catch(() => undefined);
33	    }
34	    return () => link?.remove();
35	  }, []);
36	};
37	
38	const AtlasGate = () => {
39	  const { space: spaceParam, articleSlug } = useParams<{ space?: string; articleSlug?: string }>();
40	  const { bySpace, permissionsReady } = useAtlasCapabilities();
41	  const space = getAtlasSpace(spaceParam);
42	
43	  if (!permissionsReady) return <p className="p-6 text-[14px] text-ws-ink-3">Loading…</p>;
44	
45	  const readable = listAtlasSpaces().filter((candidate) => bySpace[candidate.id]?.view);
46	  if (readable.length === 0) {
47	    return (
48	      <div className="flex h-full items-center justify-center p-6">
49	        <div className="max-w-sm space-y-2 text-center">
50	          <h1 className="ws-h1">No access</h1>
51	          <p className="ws-body text-ws-ink-2">Your role does not include any {ATLAS_CONFIG.productName} spaces. Ask an administrator to grant access.</p>
52	        </div>
53	      </div>
54	    );
55	  }
56	
57	  if (!space || !bySpace[space.id]?.view) {
58	    const fallback = readable.find((candidate) => candidate.id === ATLAS_CONFIG.defaultSpaceId) ?? readable[0];
59	    return <Navigate to={atlasPath(fallback.id)} replace />;
60	  }
61	
62	  return <AtlasWorkspace key={space.id} space={space} articleSlug={articleSlug} />;
63	};
64	
65	/** The standalone, full-screen Atlas app: no admin chrome, its own theme scope and permission context. */
66	const Passthrough = ({ children }: { children: ReactNode }) => <>{children}</>;
67	
68	const AtlasApp = () => {
69	  useAdminBodyClass();
70	  useScrollingClass();
71	  useAtlasInstall();
72	  // In a browser tab the host's chrome (site header, launcher, search, profile, help) frames Atlas;
73	  // as an installed window Atlas is the whole window and the chrome is skipped.
74	  const standalone = useStandaloneDisplay();
75	  const Frame = standalone ? Passthrough : (getAtlasHost().Frame ?? Passthrough);
76	  return (
77	    <AdminRoleProvider>
78	      <div className="admin-tool flex h-screen w-full flex-col overflow-hidden rounded-none">
79	        <Frame>
80	          <main className="admin-content h-full min-h-0 w-full flex-1 overflow-hidden p-0">
81	            <AtlasGate />
82	          </main>
83	        </Frame>
84	      </div>
85	    </AdminRoleProvider>
86	  );
87	};
88	
89	export default AtlasApp;
