1	import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
2	import { PanelLeftOpen } from "lucide-react";
3	import { SIDEBAR_MAX, SIDEBAR_MIN } from "../hooks/useAtlasPrefs";
4	
5	interface WorkspaceShellProps {
6	  sidebar: ReactNode;
7	  /** Right panel content; null keeps it closed. */
8	  panel: ReactNode | null;
9	  sidebarWidth: number;
10	  onSidebarWidthChange: (width: number) => void;
11	  sidebarCollapsed: boolean;
12	  onSidebarCollapsedChange: (collapsed: boolean) => void;
13	  children: ReactNode;
14	}
15	
16	/**
17	 * Three-pane workspace: resizable/collapsible sidebar, centre canvas, optional
18	 * right panel. Each pane scrolls on its own. Below 768px the side panes float
19	 * over the canvas instead of squeezing it.
20	 */
21	const WorkspaceShell = ({
22	  sidebar,
23	  panel,
24	  sidebarWidth,
25	  onSidebarWidthChange,
26	  sidebarCollapsed,
27	  onSidebarCollapsedChange,
28	  children,
29	}: WorkspaceShellProps) => {
30	  const dragging = useRef(false);
31	  const [narrow, setNarrow] = useState(() => typeof window !== "undefined" && window.innerWidth < 768);
32	
33	  useEffect(() => {
34	    const query = window.matchMedia("(max-width: 767px)");
35	    const update = () => setNarrow(query.matches);
36	    update();
37	    query.addEventListener("change", update);
38	    return () => query.removeEventListener("change", update);
39	  }, []);
40	
41	  // On narrow screens the side panes float over the canvas, so only one shows at a time.
42	  const showSidebar = !sidebarCollapsed && !(narrow && panel);
43	
44	  // ⌘\ / Ctrl+\ toggles the sidebar.
45	  useEffect(() => {
46	    const onKey = (event: KeyboardEvent) => {
47	      if ((event.metaKey || event.ctrlKey) && event.key === "\\") {
48	        event.preventDefault();
49	        onSidebarCollapsedChange(!sidebarCollapsed);
50	      }
51	    };
52	    window.addEventListener("keydown", onKey);
53	    return () => window.removeEventListener("keydown", onKey);
54	  }, [sidebarCollapsed, onSidebarCollapsedChange]);
55	
56	  const startResize = useCallback(
57	    (event: React.PointerEvent<HTMLDivElement>) => {
58	      event.preventDefault();
59	      dragging.current = true;
60	      const left = event.currentTarget.parentElement?.getBoundingClientRect().left ?? 0;
61	      const onMove = (move: PointerEvent) => {
62	        if (dragging.current) onSidebarWidthChange(move.clientX - left);
63	      };
64	      const onUp = () => {
65	        dragging.current = false;
66	        window.removeEventListener("pointermove", onMove);
67	        window.removeEventListener("pointerup", onUp);
68	      };
69	      window.addEventListener("pointermove", onMove);
70	      window.addEventListener("pointerup", onUp);
71	    },
72	    [onSidebarWidthChange],
73	  );
74	
75	  const onResizeKey = (event: React.KeyboardEvent<HTMLDivElement>) => {
76	    if (event.key === "ArrowLeft") onSidebarWidthChange(sidebarWidth - 16);
77	    if (event.key === "ArrowRight") onSidebarWidthChange(sidebarWidth + 16);
78	  };
79	
80	  return (
81	    <div className="relative flex h-full min-h-0 w-full overflow-hidden bg-ws-bg text-ws-ink">
82	      {showSidebar ? (
83	        <>
84	          <button
85	            type="button"
86	            aria-label="Close sidebar"
87	            className="absolute inset-0 z-20 bg-black/30 md:hidden"
88	            onClick={() => onSidebarCollapsedChange(true)}
89	          />
90	          <aside
91	            aria-label="Pages"
92	            style={{ width: sidebarWidth }}
93	            className="relative z-30 flex min-h-0 shrink-0 flex-col border-r border-ws-line bg-ws-side max-md:absolute max-md:inset-y-0 max-md:left-0 max-md:max-w-[85vw]"
94	          >
95	            {sidebar}
96	            <div
97	              role="separator"
98	              aria-orientation="vertical"
99	              aria-label="Resize sidebar"
100	              aria-valuemin={SIDEBAR_MIN}
101	              aria-valuemax={SIDEBAR_MAX}
102	              aria-valuenow={sidebarWidth}
103	              tabIndex={0}
104	              onPointerDown={startResize}
105	              onKeyDown={onResizeKey}
106	              className="absolute inset-y-0 -right-1 z-10 w-2 cursor-col-resize hover:bg-ws-accent/20 focus-visible:bg-ws-accent/30 max-md:hidden"
107	            />
108	          </aside>
109	        </>
110	      ) : (
111	        <button
112	          type="button"
113	          onClick={() => onSidebarCollapsedChange(false)}
114	          aria-label="Open sidebar (Ctrl+\)"
115	          title="Open sidebar"
116	          className="absolute left-2 top-1.5 z-40 flex h-8 w-8 items-center justify-center rounded-[6px] border border-ws-line bg-ws-paper text-ws-ink hover:bg-[var(--ws-hover)]"
117	        >
118	          <PanelLeftOpen className="h-4 w-4" />
119	        </button>
120	      )}
121	
122	      <main className="min-h-0 min-w-0 flex-1 overflow-y-auto">{children}</main>
123	
124	      {panel ? (
125	        <aside
126	          aria-label="Page panel"
127	          className="z-30 flex min-h-0 w-[340px] shrink-0 flex-col border-l border-ws-line bg-ws-paper max-md:absolute max-md:inset-y-0 max-md:right-0 max-md:w-[min(340px,100vw)]"
128	        >
129	          {panel}
130	        </aside>
131	      ) : null}
132	    </div>
133	  );
134	};
135	
136	export default WorkspaceShell;
