298	          {[...node.children].sort(bySort).map((child) => (
299	            <TreeRow key={child.id} {...props} node={child} depth={depth + 1} />
300	          ))}
301	        </div>
302	      ) : null}
303	    </div>
304	  );
305	};
306	
307	export default PageTree;
