35	export const formatRelative = (iso?: string | null): string => {
36	  if (!iso) return "never";
37	  const diff = Date.now() - new Date(iso).getTime();
38	  const minutes = Math.round(diff / 60000);
39	  if (minutes < 1) return "just now";
40	  if (minutes < 60) return `${minutes} min ago`;
41	  const hours = Math.round(minutes / 60);
42	  if (hours < 24) return `${hours} h ago`;
43	  const days = Math.round(hours / 24);
44	  if (days < 30) return `${days} d ago`;
45	  return new Date(iso).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
46	};
