1	import { useEffect, useMemo, useRef, useState, type DragEvent } from "react";
2	import { ChevronRight, Copy, FileText, FolderInput, Link2, MoreHorizontal, Pencil, Plus, Star, StarOff, Trash2 } from "lucide-react";
3	import { cn } from "@/lib/utils";
4	import {
5	  DropdownMenu,
6	  DropdownMenuContent,
7	  DropdownMenuItem,
8	  DropdownMenuSeparator,
9	  DropdownMenuTrigger,
10	} from "@/components/ui/dropdown-menu";
11	import type { TreeNode } from "../pageTree";
12	import type { AtlasPageMeta } from "../hooks/useAtlasPrefs";
13	import type { DropPosition } from "./pageTreeLogic";
14	
15	export interface PageTreeProps {
16	  nodes: TreeNode[];
17	  activeId: string | null;
18	  /** Ids whose open state differs from the default (sections open, pages closed). */
19	  toggled: Set<string>;
20	  onToggle: (id: string) => void;
21	  pageMeta: Record<string, AtlasPageMeta>;
22	  favoriteIds: string[];
23	  onToggleFavorite: (id: string) => void;
24	  onOpen: (node: TreeNode) => void;
25	  onAddChild: (node: TreeNode) => void;
26	  onRename: (id: string, title: string) => void;
27	  onDuplicate: (id: string) => void;
28	  onMoveTo: (id: string) => void;
29	  onArchive: (id: string) => void;
30	  /** Sections can be renamed (through onRename) and deleted. */
31	  onDeleteSection: (id: string) => void;
32	  onMove: (dragId: string, targetId: string, position: DropPosition) => void;
33	  canEdit: boolean;
34	}
35	
36	const bySort = (a: TreeNode, b: TreeNode) => a.sortOrder - b.sortOrder || a.title.localeCompare(b.title);
37	
38	const containsId = (node: TreeNode, id: string): boolean =>
39	  node.children.some((child) => child.id === id || containsId(child, id));
40	
41	const dropPositionFor = (event: DragEvent<HTMLElement>, isSection: boolean): DropPosition => {
42	  if (isSection) return "inside";
43	  const rect = event.currentTarget.getBoundingClientRect();
44	  const offset = (event.clientY - rect.top) / rect.height;
45	  if (offset < 0.25) return "before";
46	  if (offset > 0.75) return "after";
47	  return "inside";
48	};
49	
50	const PageTree = (props: PageTreeProps) => {
51	  const { nodes, activeId } = props;
52	  const [dragId, setDragId] = useState<string | null>(null);
53	  const [drop, setDrop] = useState<{ id: string; position: DropPosition } | null>(null);
54	  const sorted = useMemo(() => [...nodes].sort(bySort), [nodes]);
55	
56	  return (
57	    <div role="tree" aria-label="Pages" className="space-y-px px-2 pb-2">
58	      {sorted.map((node) => (
59	        <TreeRow
60	          key={node.id}
61	          node={node}
62	          depth={0}
63	          {...props}
64	          activeId={activeId}
65	          dragId={dragId}
66	          setDragId={setDragId}
67	          drop={drop}
68	          setDrop={setDrop}
69	        />
70	      ))}
71	    </div>
72	  );
73	};
74	
75	type RowProps = PageTreeProps & {
76	  node: TreeNode;
77	  depth: number;
78	  dragId: string | null;
79	  setDragId: (id: string | null) => void;
80	  drop: { id: string; position: DropPosition } | null;
81	  setDrop: (drop: { id: string; position: DropPosition } | null) => void;
82	};
83	
84	const TreeRow = (props: RowProps) => {
85	  const {
86	    node,
87	    depth,
88	    activeId,
89	    toggled,
90	    onToggle,
91	    pageMeta,
92	    favoriteIds,
93	    onToggleFavorite,
94	    onOpen,
95	    onAddChild,
96	    onRename,
97	    onDuplicate,
98	    onMoveTo,
99	    onArchive,
100	    onDeleteSection,
101	    onMove,
102	    canEdit,
103	    dragId,
104	    setDragId,
105	    drop,
106	    setDrop,
107	  } = props;
108	
109	  const isSection = node.kind === "section";
110	  const isActive = activeId === node.id;
111	  const hasChildren = node.children.length > 0;
112	  const holdsActive = activeId ? containsId(node, activeId) : false;
113	  const open = isSection ? !toggled.has(node.id) || holdsActive : toggled.has(node.id) || holdsActive;
114	  const [renaming, setRenaming] = useState(false);
115	  const [title, setTitle] = useState(node.title);
116	  const inputRef = useRef<HTMLInputElement>(null);
117	  const favorite = favoriteIds.includes(node.id);
118	  const icon = pageMeta[node.id]?.icon;
119	  const dropHere = drop?.id === node.id ? drop.position : null;
120	
121	  useEffect(() => {
122	    if (renaming) inputRef.current?.select();
123	  }, [renaming]);
124	
125	  const commitRename = () => {
126	    setRenaming(false);
127	    const next = title.trim();
128	    if (next && next !== node.title) onRename(node.id, next);
129	    else setTitle(node.title);
130	  };
131	
132	  const draggable = canEdit && !isSection && !renaming;
133	
134	  return (
135	    <div role="none">
136	      <div
137	        role="treeitem"
138	        aria-level={depth + 1}
139	        aria-selected={isActive}
140	        aria-expanded={hasChildren ? open : undefined}
141	        draggable={draggable}
142	        onDragStart={(event) => {
143	          event.dataTransfer.effectAllowed = "move";
144	          event.dataTransfer.setData("text/plain", node.id);
145	          setDragId(node.id);
146	        }}
147	        onDragEnd={() => {
148	          setDragId(null);
149	          setDrop(null);
150	        }}
151	        onDragOver={(event) => {
152	          if (!canEdit || !dragId || dragId === node.id) return;
153	          const position = dropPositionFor(event, isSection);
154	          event.preventDefault();
155	          event.dataTransfer.dropEffect = "move";
156	          if (drop?.id !== node.id || drop.position !== position) setDrop({ id: node.id, position });
157	        }}
158	        onDragLeave={(event) => {
159	          if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setDrop(null);
160	        }}
161	        onDrop={(event) => {
162	          event.preventDefault();
163	          const dragged = dragId ?? event.dataTransfer.getData("text/plain");
164	          const position = dropPositionFor(event, isSection);
165	          setDrop(null);
166	          setDragId(null);
167	          if (dragged && dragged !== node.id) onMove(dragged, node.id, position);
168	        }}
169	        style={{ paddingLeft: 4 + depth * 14 }}
170	        className={cn(
171	          "group relative flex h-7 items-center gap-1 rounded-[4px] pr-1 text-[14px] text-ws-ink-2",
172	          "hover:bg-[var(--ws-hover)] active:bg-[var(--ws-press)]",
173	          isActive && "bg-ws-side-hover font-semibold text-ws-ink",
174	          dragId === node.id && "opacity-40",
175	          dropHere === "inside" && "bg-ws-accent-tint ring-1 ring-ws-accent",
176	        )}
177	      >
178	        {dropHere === "before" ? <span className="pointer-events-none absolute inset-x-1 -top-px h-0.5 bg-ws-accent" /> : null}
179	        {dropHere === "after" ? <span className="pointer-events-none absolute inset-x-1 -bottom-px h-0.5 bg-ws-accent" /> : null}
180	
181	        <button
182	          type="button"
183	          aria-label={open ? "Collapse" : "Expand"}
184	          tabIndex={-1}
185	          onClick={() => onToggle(node.id)}
186	          className={cn(
187	            "flex h-5 w-5 shrink-0 items-center justify-center rounded-[4px] text-ws-ink-3 hover:bg-[var(--ws-press)]",
188	            !hasChildren && !isSection && "invisible",
189	          )}
190	        >
191	          <ChevronRight className={cn("h-3.5 w-3.5 transition-transform", open && "rotate-90")} />
192	        </button>
193	
194	        {renaming ? (
195	          <input
196	            ref={inputRef}
197	            value={title}
198	            onChange={(event) => setTitle(event.target.value)}
199	            onBlur={commitRename}
200	            onKeyDown={(event) => {
201	              if (event.key === "Enter") commitRename();
202	              if (event.key === "Escape") {
203	                setTitle(node.title);
204	                setRenaming(false);
205	              }
206	            }}
207	            className="h-6 min-w-0 flex-1 border border-ws-accent bg-ws-paper px-1 text-[14px] text-ws-ink outline-none"
208	            aria-label={isSection ? "Section name" : "Page title"}
209	          />
210	        ) : (
211	          <button
212	            type="button"
213	            onClick={() => (isSection ? onToggle(node.id) : onOpen(node))}
214	            className="flex min-w-0 flex-1 items-center gap-1.5 text-left"
215	          >
216	            {isSection ? null : (
217	              <span className="flex h-5 w-5 shrink-0 items-center justify-center text-[15px] leading-none text-ws-ink-3">
218	                {icon ? icon : node.kind === "link" ? <Link2 className="h-3.5 w-3.5" /> : <FileText className="h-3.5 w-3.5" />}
219	              </span>
220	            )}
221	            <span className={cn("truncate", isSection && "ws-label text-ws-ink-3")}>{node.title}</span>
222	            {!isSection && node.status === "draft" ? (
223	              <span className="ws-label ml-auto shrink-0 text-[9px] text-ws-ink-3">Draft</span>
224	            ) : null}
225	          </button>
226	        )}
227	
228	        {canEdit && !renaming ? (
229	          <span className="flex shrink-0 items-center opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100">
230	            {isSection ? (
231	              <DropdownMenu>
232	                <DropdownMenuTrigger asChild>
233	                  <button
234	                    type="button"
235	                    aria-label={`Actions for ${node.title}`}
236	                    className="flex h-5 w-5 items-center justify-center rounded-[4px] text-ws-ink-3 hover:bg-[var(--ws-press)]"
237	                  >
238	                    <MoreHorizontal className="h-3.5 w-3.5" />
239	                  </button>
240	                </DropdownMenuTrigger>
241	                <DropdownMenuContent align="start" className="w-48">
242	                  <DropdownMenuItem onSelect={() => setRenaming(true)}>
243	                    <Pencil className="mr-2 h-3.5 w-3.5" /> Rename section
244	                  </DropdownMenuItem>
245	                  <DropdownMenuSeparator />
246	                  <DropdownMenuItem onSelect={() => onDeleteSection(node.id)}>
247	                    <Trash2 className="mr-2 h-3.5 w-3.5" /> Delete section
248	                  </DropdownMenuItem>
249	                </DropdownMenuContent>
250	              </DropdownMenu>
251	            ) : null}
252	            {!isSection ? (
253	              <DropdownMenu>
254	                <DropdownMenuTrigger asChild>
255	                  <button
256	                    type="button"
257	                    aria-label={`Actions for ${node.title}`}
258	                    className="flex h-5 w-5 items-center justify-center rounded-[4px] text-ws-ink-3 hover:bg-[var(--ws-press)]"
259	                  >
260	                    <MoreHorizontal className="h-3.5 w-3.5" />
261	                  </button>
262	                </DropdownMenuTrigger>
263	                <DropdownMenuContent align="start" className="w-48">
264	                  <DropdownMenuItem onSelect={() => setRenaming(true)}>
265	                    <Pencil className="mr-2 h-3.5 w-3.5" /> Rename
266	                  </DropdownMenuItem>
267	                  <DropdownMenuItem onSelect={() => onDuplicate(node.id)}>
268	                    <Copy className="mr-2 h-3.5 w-3.5" /> Duplicate
269	                  </DropdownMenuItem>
270	                  <DropdownMenuItem onSelect={() => onMoveTo(node.id)}>
271	                    <FolderInput className="mr-2 h-3.5 w-3.5" /> Move to…
272	                  </DropdownMenuItem>
273	                  <DropdownMenuItem onSelect={() => onToggleFavorite(node.id)}>
274	                    {favorite ? <StarOff className="mr-2 h-3.5 w-3.5" /> : <Star className="mr-2 h-3.5 w-3.5" />}
275	                    {favorite ? "Remove from favorites" : "Add to favorites"}
276	                  </DropdownMenuItem>
277	                  <DropdownMenuSeparator />
278	                  <DropdownMenuItem onSelect={() => onArchive(node.id)}>
279	                    <Trash2 className="mr-2 h-3.5 w-3.5" /> Archive
280	                  </DropdownMenuItem>
281	                </DropdownMenuContent>
282	              </DropdownMenu>
283	            ) : null}
284	            <button
285	              type="button"
286	              aria-label={isSection ? `Add page to ${node.title}` : `Add page inside ${node.title}`}
287	              onClick={() => onAddChild(node)}
288	              className="flex h-5 w-5 items-center justify-center rounded-[4px] text-ws-ink-3 hover:bg-[var(--ws-press)]"
289	            >
290	              <Plus className="h-3.5 w-3.5" />
291	            </button>
292	          </span>
293	        ) : null}
294	      </div>
295	
296	      {hasChildren && open ? (
297	        <div role="group">
298	          {[...node.children].sort(bySort).map((child) => (
299	            <TreeRow key={child.id} {...props} node={child} depth={depth + 1} />
300	          ))}
301	        </div>
302	      ) : null}
303	    </div>
304	  );
305	};
306	
307	export default PageTree;
