/* Admin Tool Design Tokens
   Every --admin-* name still exists (27+ components read them) but each one now
   resolves to a --ws-* token from styles/workspace.css. Tokens flip with
   .dark, so the dark block only holds values that are not plain re-points. */
.admin-tool {
  /* Surfaces */
  --admin-topbar-bg: var(--ws-paper);
  --admin-content-bg: var(--ws-bg);
  --admin-card: var(--ws-paper);
  --admin-table-surface: var(--ws-paper);
  --admin-table-bg: var(--ws-paper);
  --admin-table-row-even: var(--ws-paper);
  --admin-table-row-odd: var(--ws-paper);
  --admin-table-row-alt: var(--ws-paper);
  --admin-overlay-surface-bg: var(--ws-paper);
  --admin-input-bg: var(--ws-paper);

  /* Sidebar */
  --admin-sidebar-bg: var(--ws-side);
  --admin-overlay-sidebar-surface-bg: var(--ws-side);
  --admin-sidebar-fg: var(--ws-ink-2);
  --admin-overlay-sidebar-surface-fg: var(--ws-ink-2);
  --admin-sidebar-hover: var(--ws-side-hover);
  --admin-sidebar-active: var(--ws-side-hover);
  --admin-sidebar-active-fg: var(--ws-ink);

  /* Text */
  --admin-content-fg: var(--ws-ink);
  --admin-table-fg: var(--ws-ink);
