/* ──────────────────────────────────────────────────────────────────────────
   Workspace block editor + shared page typography.
   `.ws-prose` is used by the editor and by admin renderings of a page so the
   two look the same. It only reads shadcn tokens, which resolve to the --ws-*
   tokens inside admin. Body 16/1.65; headings Plus Jakarta Sans 700.
   ────────────────────────────────────────────────────────────────────────── */

.ws-prose {
  font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.65;
  color: hsl(var(--foreground));
}

.ws-prose p,
.ws-prose li,
.ws-prose blockquote,
.ws-prose td,
.ws-prose th {
  color: hsl(var(--foreground));
  font-size: 16px;
  line-height: 1.65;
}

.ws-prose p {
  margin: 0.25em 0;
}

.ws-prose h1,
.ws-prose h2,
.ws-prose h3,
.ws-prose h4 {
  font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
  color: hsl(var(--foreground));
  letter-spacing: -0.01em;
  margin: 1.4em 0 0.3em;
}

