/* ──────────────────────────────────────────────────────────────────────────
   Atlas skin: a calm document-app look for the standalone Atlas workspace.
   Scope: `.admin-tool.atlas-skin` (the AtlasApp root) and `body.ws-admin.atlas-skin`
   (set while Atlas is mounted) so portaled menus, popovers and dialogs match.
   It only re-points the --ws-* tokens from styles/workspace.css and adjusts
   type and shape; every other admin screen is untouched.

   Dark values were sampled from reference screenshots; light values are estimates.
   ────────────────────────────────────────────────────────────────────────── */

.admin-tool.atlas-skin,
body.ws-admin.atlas-skin {
  --ws-paper: 0 0% 100%;
  --ws-bg: 0 0% 100%;
  --ws-side: 60 9% 97%;
  --ws-side-hover: 60 5% 93.5%;
  --ws-ink: 45 8% 20%;
  --ws-ink-2: 45 2% 46%;
  --ws-ink-3: 45 2% 60%;
  --ws-line: 60 5% 91%;
  --ws-input-border: 60 1% 87%;
  --ws-accent: 210 76% 51%;
  --ws-accent-fg: 0 0% 100%;
  --ws-accent-tint: 210 70% 95%;
  --ws-accent-line: 210 76% 51%;
  --ws-thumb: 45 2% 60%;

  --ws-hover: hsl(45 8% 20% / 0.06);
  --ws-press: hsl(45 8% 20% / 0.1);
  --ws-selection: hsl(210 76% 51% / 0.2);

  --ws-radius-block: 4px;
  --ws-radius-control: 6px;
  --ws-radius-float: 10px;

  --ws-font-sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI Variable Display", "Segoe UI", Helvetica,
    "Apple Color Emoji", Arial, sans-serif, "Segoe UI Emoji", "Segoe UI Symbol";

  --atlas-float-shadow: 0 0 0 1px hsl(45 8% 20% / 0.08), 0 3px 6px hsl(45 8% 20% / 0.08), 0 9px 24px hsl(45 8% 20% / 0.16);
}

.dark .admin-tool.atlas-skin,
.dark body.ws-admin.atlas-skin {
  --ws-paper: 0 0% 14.5%;
  --ws-bg: 0 0% 10%;
  --ws-side: 0 0% 12.5%;
  --ws-side-hover: 0 0% 17.3%;
  --ws-ink: 0 0% 83%;
  --ws-ink-2: 0 0% 61%;
  --ws-ink-3: 38 3% 47%;
  --ws-line: 60 2% 21%;
  --ws-input-border: 60 2% 21%;
  --ws-accent: 210 74% 51%;
  --ws-accent-fg: 0 0% 100%;
  --ws-accent-tint: 210 40% 18%;
  --ws-accent-line: 210 74% 51%;
  --ws-thumb: 0 0% 50%;

  --ws-hover: hsl(0 0% 100% / 0.055);
  --ws-press: hsl(0 0% 100% / 0.09);
  --ws-selection: hsl(210 74% 51% / 0.3);

  --atlas-float-shadow: 0 0 0 1px hsl(60 2% 21%), 0 3px 6px hsl(0 0% 0% / 0.2), 0 9px 24px hsl(0 0% 0% / 0.4);
}

/* Type: the system UI face everywhere, 14px chrome, 16/1.5 page text. */
.atlas-skin,
.atlas-skin :is(.ws-prose, .ws-prose h1, .ws-prose h2, .ws-prose h3, .ws-prose h4) {
  font-family: var(--ws-font-sans);
}

.atlas-skin .ws-label {
  font-family: var(--ws-font-sans);
  font-size: 12px;
  line-height: 1.3;
  font-weight: 500;
  text-transform: none;
  letter-spacing: 0;
}

.atlas-skin .ws-page-title {
  font-size: 40px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: 0;
}

.atlas-skin .ws-body,
.atlas-skin .ws-prose,
.atlas-skin .ws-prose :is(p, li, blockquote) {
  line-height: 1.5;
}

.atlas-skin .ws-prose :is(h1, h2, h3, h4) {
  letter-spacing: 0;
  font-weight: 600;
  margin: 1.1em 0 0.2em;
}

.atlas-skin .ws-prose h1 { font-size: 30px; line-height: 1.3; }
.atlas-skin .ws-prose h2 { font-size: 24px; line-height: 1.3; }
.atlas-skin .ws-prose h3 { font-size: 20px; line-height: 1.3; }

/* Floating layers: rounded 10px panels with a soft border and deep shadow. */
.atlas-skin :is([role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"], [data-radix-popper-content-wrapper] > *) {
  border-radius: var(--ws-radius-float);
  border-color: hsl(var(--ws-line));
  background-color: hsl(var(--ws-paper));
  box-shadow: var(--atlas-float-shadow);
}

.atlas-skin :is([role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"]) {
  min-height: 28px;
  border-radius: var(--ws-radius-control);
  font-size: 14px;
}

.atlas-skin [role="menu"] [role="separator"] {
  background-color: hsl(var(--ws-line));
}

/* Inline page title: no filled field behind it. */
.atlas-skin textarea.ws-bare-input,
.atlas-skin input.ws-bare-input {
  background-color: transparent !important;
  border-color: transparent !important;
}

