/* ──────────────────────────────────────────────────────────────────────────
   Atlas theme: a calm, document-first workspace look (warm greys, one blue
   accent, the system UI font, airy page column).

   Scope: the Atlas canvas (`.admin-tool.ws-atlas`, nested inside the host's
   admin shell so the host chrome keeps its own look) and `body.ws-atlas`
   (set while Atlas is mounted) for portaled menus, popovers and dialogs.
   Only --ws-* tokens and Atlas-scoped rules live here; workspace.css stays
   the theme for the rest of admin.
   ────────────────────────────────────────────────────────────────────────── */

.admin-tool.ws-atlas,
body.ws-admin.ws-atlas {
  --ws-paper: 0 0% 100%;
  --ws-bg: 0 0% 100%;
  --ws-side: 60 11% 96%;
  --ws-side-hover: 60 4% 92%;
  --ws-side-ink: 45 2% 36%;
  --ws-ink: 45 8% 20%;
  --ws-ink-2: 45 2% 47%;
  --ws-ink-3: 45 2% 60%;
  --ws-line: 60 2% 93%;
  --ws-input-border: 60 3% 87%;
  --ws-accent: 210 77% 51%;
  --ws-accent-fg: 0 0% 100%;
  --ws-accent-tint: 205 60% 94%;
  --ws-accent-line: 45 8% 20%;
  --ws-thumb: 45 3% 64%;

  --ws-hover: hsl(var(--ws-ink) / 0.06);
  --ws-press: hsl(var(--ws-ink) / 0.12);
  --ws-selection: hsl(var(--ws-accent) / 0.28);

  --ws-radius-block: 4px;
  --ws-radius-control: 6px;
  --ws-radius-float: 10px;

  --ws-font-sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, 'Segoe UI Variable Display', 'Segoe UI', Helvetica,
    'Apple Color Emoji', Arial, sans-serif, 'Segoe UI Emoji', 'Segoe UI Symbol';
  --ws-font-serif: Lyon-Text, Georgia, ui-serif, serif;
  --ws-font-mono: 'SFMono-Regular', Menlo, Consolas, 'PT Mono', 'Liberation Mono', Courier, monospace;
  --ws-float-shadow: 0 0 0 1px hsl(0 0% 6% / 0.05), 0 3px 6px hsl(0 0% 6% / 0.1), 0 9px 24px hsl(0 0% 6% / 0.2);

  --ws-c-gray: 45 2% 46%;     --ws-t-gray: 60 6% 94%;
