64	}
65	
66	/** One sidebar row: 30px tall, 18px icon, medium-weight label. */
67	const rowClass =
68	  "flex h-[30px] w-full min-w-0 items-center gap-2 rounded-[6px] px-2 text-left text-[14px] font-medium text-[hsl(var(--atlas-side-ink))] hover:bg-[var(--ws-hover)] active:bg-[var(--ws-press)]";
