82	  badge,
83	  onClick,
84	}: {
85	  icon: typeof Search;
86	  label: string;
87	  hint?: string;
88	  badge?: number;
89	  onClick?: () => void;
90	}) => (
91	  <button type="button" onClick={onClick} className={rowClass}>
92	    <Icon className="h-[18px] w-[18px] shrink-0 opacity-80" strokeWidth={1.75} />
93	    <span className="flex-1 truncate">{label}</span>
94	    {badge ? (
95	      <span className="rounded-[4px] bg-ws-accent px-1.5 text-[11px] font-semibold text-[hsl(var(--ws-accent-fg))]">{badge}</span>
96	    ) : null}
97	    {hint ? <kbd className="text-[11px] font-normal text-ws-ink-3">{hint}</kbd> : null}
98	  </button>
99	);
100	
101	const SectionLabel = ({ children }: { children: string }) => (
102	  <p className="px-2 pb-1 pt-4 text-[12px] font-medium text-ws-ink-3">{children}</p>
103	);
104	
105	const WorkspaceSidebar = ({
106	  tree,
107	  articles,
108	  archived,
109	  userId,
110	  brand,
111	  space,
112	  spaces,
113	  onSelectSpace,
114	  canCreate,
115	  canEdit,
116	  pagePath,
117	  showAssignments,
118	  showTree,
119	  appLinks,
120	  onSearch,
121	  onAskIris,
122	  onNewPage,
123	  onRestore,
124	  onCollapse,
