132	  const updates = useMemo(() => {
133	    const cutoff = Math.max(seenAt, Date.now() - WEEK_MS);
134	    return articles
135	      .filter((article) => article.status !== "archived" && new Date(article.updatedAt).getTime() > cutoff)
136	      .filter((article) => !userId || (article.lastEditedBy ?? article.authorId) !== userId)
137	      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
