180	            {new Date(article.updatedAt).toLocaleDateString(undefined, { month: "short", day: "numeric" })}
181	          </span>
182	        </button>
183	      ))}
184	      {articles.length === 0 ? <p className="px-2 py-2 text-[13px] text-ws-ink-3">No pages yet.</p> : null}
185	    </PopoverContent>
186	  );
187	
188	  return (
189	    <>
190	      <div className="flex h-11 shrink-0 items-center gap-1 px-3">
191	        <button type="button" aria-label="Collapse sidebar (Ctrl+\)" title="Collapse sidebar" onClick={onCollapse} className={iconButtonClass}>
192	          <PanelLeft className="h-[18px] w-[18px]" strokeWidth={1.75} />
193	        </button>
194	        <span className="flex-1" />
195	        <Popover onOpenChange={onUpdatesOpen}>
196	          <PopoverTrigger asChild>
197	            <button type="button" aria-label="Updates" title="Updates" className={cn(iconButtonClass, "relative")}>
198	              <Inbox className="h-[18px] w-[18px]" strokeWidth={1.75} />
199	              {updates.length > 0 ? <span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-ws-accent" /> : null}
200	            </button>
201	          </PopoverTrigger>
202	          {updatesList}
203	        </Popover>
