215	          className="flex h-8 w-full items-center gap-2 rounded-[8px] border border-ws-line px-2.5 text-left text-[14px] text-ws-ink-3 hover:bg-[var(--ws-hover)]"
216	        >
217	          <span className="flex-1 truncate">Search or ask</span>
218	          <kbd className="rounded-[4px] bg-ws-line px-1 font-sans text-[11px] text-ws-ink-2">Ctrl+K</kbd>
219	        </button>
