231	          <MessageCircle className="h-[18px] w-[18px]" strokeWidth={1.75} />
232	        </button>
233	        <Popover onOpenChange={onUpdatesOpen}>
234	          <PopoverTrigger asChild>
235	            <button type="button" aria-label="Recent pages" title="Recent pages" className={iconButtonClass}>
236	              <CalendarDays className="h-[18px] w-[18px]" strokeWidth={1.75} />
237	            </button>
238	          </PopoverTrigger>
239	          {updatesList}
240	        </Popover>
241	      </div>
242	
243	      <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-2">
244	        <div className="space-y-px">
245	          {canCreate ? <SidebarButton icon={SquarePen} label="New page" onClick={onNewPage} /> : null}
246	          <SidebarButton icon={MessageCirclePlus} label="Ask Iris" hint="Ctrl J" onClick={onAskIris} />
247	          {showAssignments ? <SidebarButton icon={ListChecks} label="Assignments" onClick={onOpenAssignments} /> : null}
248	        </div>
249	
250	        {favorites.length > 0 ? (
251	          <section aria-label="Favorites">
