  --ws-c-yellow: 45 67% 55%;  --ws-t-yellow: 45 38% 17%;
  --ws-c-green: 150 43% 55%;  --ws-t-green: 150 32% 16%;
  --ws-c-blue: 209 69% 64%;   --ws-t-blue: 209 40% 19%;
  --ws-c-purple: 274 43% 69%; --ws-t-purple: 274 28% 21%;
  --ws-c-pink: 329 62% 68%;   --ws-t-pink: 329 30% 21%;
  --ws-c-red: 3 76% 69%;      --ws-t-red: 3 38% 20%;
