body.ws-admin.ws-atlas :is([data-radix-popper-content-wrapper], [role='dialog'], [role='alertdialog']) {
  font-family: var(--ws-font-sans);
}

/* Floating layers: a soft three-step shadow, larger radius. */
:is(.ws-atlas, body.ws-atlas) :is([role='dialog'], [role='alertdialog'], [role='menu'], [role='listbox'], [data-radix-popper-content-wrapper] > *) {
  border-radius: var(--ws-radius-float);
  border-color: transparent;
  box-shadow: var(--ws-float-shadow);
}

body.ws-atlas [role='menuitem'] {
  font-size: 14px;
  min-height: 28px;
}

/* Section labels: small grey sentence case instead of mono capitals. */
:is(.ws-atlas, body.ws-atlas) .ws-label {
  font-family: var(--ws-font-sans);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
}

.ws-atlas .ws-page-title {
  font-size: 40px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: normal;
}

.ws-atlas .ws-h1 { font-size: 30px; line-height: 1.3; font-weight: 600; letter-spacing: normal; }
.ws-atlas .ws-h2 { font-size: 24px; line-height: 1.3; font-weight: 600; letter-spacing: normal; }
.ws-atlas .ws-h3 { font-size: 20px; line-height: 1.3; font-weight: 600; letter-spacing: normal; }
.ws-atlas .ws-body { font-size: 16px; line-height: 1.5; }

/* Opaque tag tints */
:is(.ws-atlas, body.ws-atlas) .ws-bg-gray   { background-color: hsl(var(--ws-t-gray)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-brown  { background-color: hsl(var(--ws-t-brown)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-orange { background-color: hsl(var(--ws-t-orange)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-yellow { background-color: hsl(var(--ws-t-yellow)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-green  { background-color: hsl(var(--ws-t-green)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-blue   { background-color: hsl(var(--ws-t-blue)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-purple { background-color: hsl(var(--ws-t-purple)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-pink   { background-color: hsl(var(--ws-t-pink)); }
:is(.ws-atlas, body.ws-atlas) .ws-bg-red    { background-color: hsl(var(--ws-t-red)); }

/* Database tables: plain grey headers with column lines. */
.ws-atlas table th {
  font-family: var(--ws-font-sans);
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
  color: hsl(var(--ws-ink-2));
  padding: 7px 8px;
  border-right: 1px solid hsl(var(--ws-line));
}

.ws-atlas table td {
  font-size: 14px;
  padding: 7px 8px;
  border-right: 1px solid hsl(var(--ws-line));
}

.ws-atlas table :is(th, td):last-child {
  border-right: 0;
}

/* ── Page content ───────────────────────────────────────────────────────── */

.ws-atlas .ws-prose {
  font-family: var(--ws-font-sans);
  font-size: 16px;
  line-height: 1.5;
}

.ws-atlas .ws-prose :is(p, li, blockquote, td, th) {
  font-size: inherit;
  line-height: 1.5;
}

.ws-atlas .ws-prose p {
  margin: 1px 0;
  padding: 3px 2px;
}

.ws-atlas .ws-prose :is(h1, h2, h3, h4) {
  font-family: inherit;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: normal;
  padding: 3px 2px;
  margin-bottom: 1px;
}

.ws-atlas .ws-prose h1 { font-size: 1.875em; margin-top: 2em; }
.ws-atlas .ws-prose h2 { font-size: 1.5em; margin-top: 1.4em; }
.ws-atlas .ws-prose h3 { font-size: 1.25em; margin-top: 1em; }
.ws-atlas .ws-prose h4 { font-size: 1em; margin-top: 1em; }
.ws-atlas .ws-prose > :first-child { margin-top: 0; }

.ws-atlas .ws-prose :is(ul, ol) {
  padding-left: 1.7em;
}

.ws-atlas .ws-prose li {
  padding: 3px 0;
}

.ws-atlas .ws-prose li::marker {
  color: hsl(var(--ws-ink));
}

.ws-atlas .ws-prose blockquote {
  margin: 4px 0;
  padding: 3px 2px 3px 14px;
  border-left: 3px solid currentColor;
}

.ws-atlas .ws-prose :is(a, .ws-link) {
  color: inherit;
  text-decoration-color: hsl(var(--ws-ink) / 0.4);
  text-underline-offset: 3px;
}

.ws-atlas .ws-prose hr {
  margin: 12px 0;
  border-top-color: hsl(var(--ws-ink) / 0.16);
}

.ws-atlas .ws-prose :is(.ws-inline-code, :not(pre) > code) {
  font-family: var(--ws-font-mono);
  font-size: 85%;
  padding: 0.2em 0.4em;
  border-radius: 4px;
  background: hsl(40 8% 50% / 0.15);
  color: #eb5757;
}

.ws-atlas .ws-prose :is(pre, .ws-code) {
  margin: 4px 0;
  padding: 32px 16px 32px 32px;
  border: 0;
  border-radius: 4px;
  background: hsl(var(--ws-side));
  font-family: var(--ws-font-mono);
  font-size: 85%;
  line-height: 1.5;
  tab-size: 2;
}

.ws-atlas .ws-prose :is(img, .ws-image) {
  border: 0;
  border-radius: 4px;
}

.ws-atlas .ws-prose :is(.ws-mention, .ws-secret, .ws-dropdown) {
  background: hsl(var(--ws-t-gray));
}

.ws-atlas .ws-prose :is(table, .ws-table) {
  margin: 4px 0;
}

.ws-atlas .ws-prose :is(th, td) {
  border-color: hsl(var(--ws-input-border));
  padding: 7px 9px;
  font-size: 14px;
}

.ws-atlas .ws-prose th {
  background: hsl(var(--ws-side));
  color: hsl(var(--ws-ink));
  font-weight: 600;
}

.ws-atlas .ws-editor .ws-callout-node,
.ws-atlas .ws-prose .ws-callout {
  margin: 4px 0;
  padding: 16px 16px 16px 12px;
  border: 0;
  background: hsl(var(--ws-t-gray));
}

.ws-atlas .ws-editor .ws-page-link-node {
  border: 0;
  padding: 3px 2px;
  text-decoration: underline;
  text-decoration-color: hsl(var(--ws-ink) / 0.25);
  text-underline-offset: 3px;
}

.ws-atlas .ws-editor .ProseMirror-selectednode {
  outline: 0;
  background: hsl(var(--ws-accent) / 0.14);
}

/* Page style: font and small text, chosen from the page actions menu. */
.ws-atlas [data-page-font='serif'] :is(.ws-page-title, .ws-prose, .ws-prose :is(h1, h2, h3, h4)) {
  font-family: var(--ws-font-serif);
}

.ws-atlas [data-page-font='mono'] :is(.ws-page-title, .ws-prose, .ws-prose :is(h1, h2, h3, h4)) {
  font-family: var(--ws-font-mono);
}

.ws-atlas [data-small-text='true'] .ws-prose {
  font-size: 14px;
}

